<?php
defined('ABSPATH') || exit;

function sanro_dm_admin_sections() {
    return array('dashboard'=>'Dashboard','assets'=>'Assets','templates'=>'Templates','fonts'=>'Fonts','providers'=>'Provider API','watermark'=>'Watermark','storage'=>'Storage & Quota','bridge'=>'Studio Bridge','diagnostics'=>'Diagnostics');
}
function sanro_dm_admin_menu() {
    add_menu_page('SANRO Design Maker','SANRO Design Maker','manage_options','sanro-design-maker','sanro_dm_admin_page','dashicons-art');
    foreach(sanro_dm_admin_sections() as $slug=>$label) add_submenu_page('sanro-design-maker','SANRO Design Maker — '.$label,$label,'manage_options','sanro-dm-'.$slug,'sanro_dm_admin_page');
}
function sanro_dm_admin_page() {
    if(!current_user_can('manage_options'))return;
    $page=isset($_GET['page'])?sanitize_key(wp_unslash($_GET['page'])):'sanro-design-maker';$section=$page==='sanro-design-maker'?'dashboard':str_replace('sanro-dm-','',$page);if(!isset(sanro_dm_admin_sections()[$section]))$section='dashboard';
    echo '<div class="wrap"><h1>SANRO Design Maker — '.esc_html(sanro_dm_admin_sections()[$section]).'</h1><nav class="nav-tab-wrapper">';
    foreach(sanro_dm_admin_sections() as $slug=>$label){$url=$slug==='dashboard'?admin_url('admin.php?page=sanro-design-maker'):admin_url('admin.php?page=sanro-dm-'.$slug);echo '<a class="nav-tab'.($section===$slug?' nav-tab-active':'').'" href="'.esc_url($url).'">'.esc_html($label).'</a>';}
    echo '</nav>';
    if($section==='dashboard')sanro_dm_admin_dashboard();elseif($section==='assets')sanro_dm_admin_assets();elseif($section==='templates')sanro_dm_admin_templates();elseif($section==='fonts')sanro_dm_admin_fonts();elseif($section==='providers')sanro_dm_admin_providers();elseif($section==='watermark')sanro_dm_admin_watermark();elseif($section==='storage')sanro_dm_admin_storage();elseif($section==='bridge')sanro_dm_admin_bridge();else sanro_dm_admin_diagnostics();echo '</div>';
}
function sanro_dm_admin_dashboard() {
    global $wpdb;$t=sanro_dm_tables();$designs=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$t['designs']}");$assets=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$t['assets']}");$fonts=get_option('sanro_dm_fonts',array());$templates=get_option('sanro_dm_templates',array());
    echo '<p>Free to design. Pay to print.</p><div class="notice notice-info inline"><p>Designs: '.esc_html((string)$designs).' · Private assets: '.esc_html((string)$assets).' · Managed templates: '.count((array)$templates).' · Local fonts: '.count((array)$fonts).'</p></div><p>Per-account limits: 100 designs, 100 assets, 64 MiB assets. Upload limit: 8 MiB and 32 megapixels.</p>';
}
function sanro_dm_admin_assets() {
    global $wpdb;$t=sanro_dm_tables();$rows=$wpdb->get_results("SELECT id,user_id,mime,bytes,source_url,attribution,license,license_url,created_at FROM {$t['assets']} ORDER BY created_at DESC LIMIT 100");
    echo '<p>Private assets and their source/license record. Deletion is allowed only for assets not referenced by a design.</p><table class="widefat striped"><thead><tr><th>Asset</th><th>Owner</th><th>Type/size</th><th>Provenance &amp; license</th><th>Action</th></tr></thead><tbody>';
    foreach((array)$rows as $r){echo '<tr><td><code>'.esc_html($r->id).'</code></td><td>'.esc_html((string)$r->user_id).'</td><td>'.esc_html($r->mime).' / '.esc_html(size_format((int)$r->bytes)).'</td><td>'.esc_html($r->attribution?:'Customer upload').'<br>'.esc_html($r->license?:'').'<br>'.($r->source_url?'<a href="'.esc_url($r->source_url).'" rel="noopener noreferrer">Source</a>':'').' '.($r->license_url?'<a href="'.esc_url($r->license_url).'" rel="noopener noreferrer">License</a>':'').'</td><td><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="sanro_dm_delete_asset"><input type="hidden" name="asset_id" value="'.esc_attr($r->id).'">';wp_nonce_field('sanro_dm_delete_asset_'.$r->id);submit_button('Delete unused','delete small',null,false);echo '</form></td></tr>';}
    if(!$rows)echo '<tr><td colspan="5">No uploaded assets.</td></tr>';echo '</tbody></table>';
}
function sanro_dm_validate_template_catalog($raw) {
    if(!is_array($raw)||count($raw)>100)return new WP_Error('invalid_templates','Provide up to 100 template records.');$out=array();
    foreach($raw as $item){if(!is_array($item)||empty($item['id'])||empty($item['title'])||empty($item['design']))return new WP_Error('invalid_templates','Every template needs id, title and design JSON.');$id=sanitize_key($item['id']);$title=sanitize_text_field($item['title']);$json=is_string($item['design'])?$item['design']:wp_json_encode($item['design']);$design=json_decode($json,true);if(!$id||strlen($title)>120||strlen($json)>512*1024||!is_array($design)||!isset($design['objects'])||!is_array($design['objects'])||count($design['objects'])>150)return new WP_Error('invalid_templates','Template record failed validation.');$allowedTypes=array('rect','circle','triangle','line','textbox','i-text','text');foreach($design['objects'] as $object)if(!isset($object['type'])||!in_array($object['type'],$allowedTypes,true))return new WP_Error('invalid_templates','Templates may contain only editable text and basic vector shapes.');$unsafe=false;$walk=function($value,$key='')use(&$walk,&$unsafe){if(is_array($value)){foreach($value as $k=>$v)$walk($v,(string)$k);return;}if(in_array($key,array('src','assetId'),true))$unsafe=true;if(is_string($value)&&preg_match('/^data:/i',$value))$unsafe=true;if(is_string($value)&&preg_match('/url\s*\(/i',$value))$unsafe=true;};$walk($design);if($unsafe)return new WP_Error('invalid_templates','Templates cannot contain private asset references, embedded data or external URLs.');$out[]=array('id'=>$id,'title'=>$title,'design'=>$design);}
    return $out;
}
function sanro_dm_admin_templates() {
    $value=get_option('sanro_dm_templates',array());echo '<p>Templates are editable Fabric JSON. Embedded image data and external image URLs are rejected; use native vector/text objects or approved private assets.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="sanro_dm_save_templates">';wp_nonce_field('sanro_dm_save_templates');echo '<textarea name="templates_json" rows="18" class="large-text code">'.esc_textarea(wp_json_encode($value,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)).'</textarea>';submit_button('Save templates');echo '</form>';
}
function sanro_dm_font_families() { return array('Poppins','Montserrat','Anton','Bebas Neue','Oswald','Bungee','Pacifico','Permanent Marker'); }
function sanro_dm_font_source_matches($family,$source) {$p=wp_parse_url($source);if(!$p||strtolower($p['scheme']??'')!=='https'||strtolower($p['host']??'')!=='fonts.google.com')return false;$slug=rawurldecode(basename(rtrim($p['path']??'','/')));return strcasecmp(str_replace('+',' ',$slug),$family)===0;}
function sanro_dm_admin_fonts() {
    $fonts=(array)get_option('sanro_dm_fonts',array());echo '<p>Bundled Anton and administrator-uploaded Google Fonts are served locally. Faces use <code>font-display:swap</code> and are fetched only when used.</p><table class="widefat striped"><thead><tr><th>Family</th><th>File</th><th>License/source</th><th>Action</th></tr></thead><tbody><tr><td>Anton</td><td>Bundled local TrueType</td><td>OFL 1.1 · <a href="https://fonts.google.com/specimen/Anton" rel="noopener noreferrer">Google Fonts</a> · packaged license in assets/fonts/Anton-OFL.txt</td><td>Bundled</td></tr>';foreach($fonts as $font){echo '<tr><td>'.esc_html($font['family']).'</td><td>'.esc_html($font['file']).'</td><td>'.esc_html($font['license']).' · <a href="'.esc_url($font['source']).'" rel="noopener noreferrer">Google Fonts source</a></td><td><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="sanro_dm_delete_font"><input type="hidden" name="family" value="'.esc_attr($font['family']).'">';wp_nonce_field('sanro_dm_delete_font_'.$font['family']);submit_button('Delete','delete small',null,false);echo '</form></td></tr>';}echo '</tbody></table><h2>Add local WOFF2</h2><form enctype="multipart/form-data" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="sanro_dm_upload_font">';wp_nonce_field('sanro_dm_upload_font');echo '<label>Family <select name="family">';foreach(sanro_dm_font_families() as $family)echo '<option>'.esc_html($family).'</option>';echo '</select></label> <label>License <select name="license"><option value="OFL">SIL Open Font License</option><option value="Apache-2.0">Apache 2.0</option></select></label> <label>Google Fonts page URL <input name="source" type="url" required></label><input type="file" name="font_file" accept=".woff2,font/woff2" required>';submit_button('Upload font');echo '</form>';
}
function sanro_dm_admin_providers() {echo '<p><strong>Openverse:</strong> official public API; search requests filter to commercial-use license types. Only CC0, public-domain mark, CC BY and CC BY-SA items are exposed. Attribution and source/license links are persisted with imported assets.</p><p><strong>Pixabay:</strong> disabled. The API does not provide per-item terms that this plugin can verify as suitable for merchandise printing.</p><p>Server proxy accepts HTTPS only, rejects private/reserved IP resolutions, disables redirects, caps response bytes and revalidates image MIME and dimensions.</p>';}
function sanro_dm_admin_watermark() {if(isset($_GET['updated']))echo '<div class="notice notice-success"><p>Watermark setting saved.</p></div>';echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="sanro_dm_save_watermark">';wp_nonce_field('sanro_dm_save_watermark');echo '<label>Preview watermark text <input class="regular-text" name="watermark" maxlength="80" value="'.esc_attr(get_option('sanro_dm_watermark','kaoscetak.id')).'"></label>';submit_button('Save watermark');echo '<p>Preview only. Production master rendering is not available in this build.</p></form>';}
function sanro_dm_admin_storage() {echo '<p>Private files resolve outside WordPress and document roots or writes fail closed.</p><ul><li>Design quota: 100 per account, up to 2 MiB serialized design each.</li><li>Asset quota: 100 / 64 MiB per account.</li><li>Image upload: 8 MiB, 8,000 × 8,000 px, at most 32 megapixels.</li><li>Expired unreferenced assets: collected after 180 days; referenced assets are retained.</li></ul><p>Master render and production export: NOT IMPLEMENTED.</p>';}
function sanro_dm_admin_bridge() {echo '<p>Studio Bridge is not enabled. The Studio source contract is documented in <code>docs/STUDIO-CONTRACT-READONLY.md</code>; staging endpoints and feature flags are not verified. No endpoint is configured here.</p>';}
function sanro_dm_admin_diagnostics() {echo '<ul><li>PHP: '.esc_html(PHP_VERSION).'</li><li>Image MIME inspection: '.(class_exists('finfo')?'available':'unavailable').'</li><li>Openverse provider code: loaded</li><li>Local font files: '.count((array)get_option('sanro_dm_fonts',array())).'</li><li>Private storage: checked on first private asset operation; not probed from this admin page.</li></ul>';}
function sanro_dm_admin_save_templates() {
    if(!current_user_can('manage_options'))wp_die('Forbidden',403);check_admin_referer('sanro_dm_save_templates');$raw=wp_unslash($_POST['templates_json']??'[]');$decoded=json_decode($raw,true);$valid=sanro_dm_validate_template_catalog($decoded);if(is_wp_error($valid))wp_die(esc_html($valid->get_error_message()),400);update_option('sanro_dm_templates',$valid,false);wp_safe_redirect(admin_url('admin.php?page=sanro-dm-templates&updated=1'));exit;
}
function sanro_dm_admin_save_watermark() {if(!current_user_can('manage_options'))wp_die('Forbidden',403);check_admin_referer('sanro_dm_save_watermark');update_option('sanro_dm_watermark',sanitize_text_field(wp_unslash($_POST['watermark']??'kaoscetak.id')),false);wp_safe_redirect(admin_url('admin.php?page=sanro-dm-watermark&updated=1'));exit;}
function sanro_dm_admin_upload_font() {
    if(!current_user_can('manage_options'))wp_die('Forbidden',403);check_admin_referer('sanro_dm_upload_font');$family=sanitize_text_field(wp_unslash($_POST['family']??''));$license=sanitize_text_field(wp_unslash($_POST['license']??''));$source=esc_url_raw(wp_unslash($_POST['source']??''));$file=$_FILES['font_file']??null;
    if(!in_array($family,sanro_dm_font_families(),true)||!in_array($license,array('OFL','Apache-2.0'),true)||!sanro_dm_font_source_matches($family,$source)||!is_array($file)||!isset($file['error'],$file['size'],$file['name'],$file['tmp_name'])||$file['error']!==UPLOAD_ERR_OK||(int)$file['size']>3*MB_IN_BYTES||strtolower(pathinfo($file['name'],PATHINFO_EXTENSION))!=='woff2'||!is_uploaded_file($file['tmp_name'])||file_get_contents($file['tmp_name'],false,null,0,4)!=='wOF2')wp_die('Font upload rejected: use an approved family, matching Google Fonts source, valid WOFF2 and open license.',400);
    $uploads=wp_upload_dir();if(!empty($uploads['error']))wp_die('Upload storage unavailable.',500);$dir=trailingslashit($uploads['basedir']).'sanro-design-maker-fonts';if(!wp_mkdir_p($dir))wp_die('Font storage unavailable.',500);$name=sanitize_file_name($family).'-'.substr(hash_file('sha256',$file['tmp_name']),0,12).'.woff2';if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))wp_die('Font storage failed.',500);@chmod($dir.'/'.$name,0644);$fonts=(array)get_option('sanro_dm_fonts',array());$fonts[$family]=array('family'=>$family,'file'=>$name,'url'=>trailingslashit($uploads['baseurl']).'sanro-design-maker-fonts/'.rawurlencode($name),'license'=>$license,'source'=>$source);update_option('sanro_dm_fonts',$fonts,false);wp_safe_redirect(admin_url('admin.php?page=sanro-dm-fonts&updated=1'));exit;
}
function sanro_dm_admin_delete_font() {
    if(!current_user_can('manage_options'))wp_die('Forbidden',403);$family=sanitize_text_field(wp_unslash($_POST['family']??''));check_admin_referer('sanro_dm_delete_font_'.$family);$fonts=(array)get_option('sanro_dm_fonts',array());if(isset($fonts[$family])){$uploads=wp_upload_dir();$dir=realpath(trailingslashit($uploads['basedir']).'sanro-design-maker-fonts');$file=$dir?realpath($dir.'/'.$fonts[$family]['file']):false;if($file&&strpos($file,$dir.DIRECTORY_SEPARATOR)===0&&is_file($file)&&!@unlink($file))wp_die('Font file could not be removed.',500);unset($fonts[$family]);update_option('sanro_dm_fonts',$fonts,false);}wp_safe_redirect(admin_url('admin.php?page=sanro-dm-fonts&deleted=1'));exit;
}
function sanro_dm_admin_delete_asset() {
    global $wpdb;if(!current_user_can('manage_options'))wp_die('Forbidden',403);$id=sanitize_text_field(wp_unslash($_POST['asset_id']??''));check_admin_referer('sanro_dm_delete_asset_'.$id);$t=sanro_dm_tables();$referenced=$wpdb->get_var($wpdb->prepare("SELECT id FROM {$t['designs']} WHERE design LIKE %s LIMIT 1",'%'.$wpdb->esc_like($id).'%'));if($referenced)wp_die('Asset is still referenced by a saved design.',409);$asset=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['assets']} WHERE id=%s",$id));if($asset){$root=sanro_dm_private_root();if(is_wp_error($root))wp_die('Private storage unavailable.',503);$path=realpath($root.'/'.$asset->path);if($path&&strpos($path,$root.DIRECTORY_SEPARATOR)===0&&is_file($path)&&!@unlink($path))wp_die('Private asset could not be removed.',500);$wpdb->delete($t['assets'],array('id'=>$id),array('%s'));}wp_safe_redirect(admin_url('admin.php?page=sanro-dm-assets&deleted=1'));exit;
}
